import {readFile,writeFile} from 'node:fs/promises';import {dirname,resolve} from 'node:path';import {fileURLToPath} from 'node:url';import vm from 'node:vm';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const root=dirname(fileURLToPath(import.meta.url)),sha=b=>createHash('sha256').update(b).digest('hex'),bundle=await readFile(resolve(root,'../geo-inverse-d3-oracle.js')),license=await readFile(resolve(root,'../geo-inverse-d3-LICENSE.txt'));assert.equal(sha(bundle),'873638c3542defc67135946f1dae3a1d0426c147989b339a8033ce39e4e92550');assert.equal(sha(license),'6c28d42e4014c126c953198f9bde4dba985d4215e5d0d33b06c7b4a1568417ce');const context=vm.createContext({});new vm.Script(bundle.toString()).runInContext(context);const d3=context.d3,R=Math.PI/180,raw=d3.geoConicEqualAreaRaw(29.5*R,45.5*R),camera=d3.geoRotation([-15,5,-18]),intrinsic=d3.geoRotation([96,0,0]),origin=raw(-.6*R,38.7*R),scale=228.43197642765313,center=[.6946014848802866,.6101266266362744],lo=71.34261557508631,hi=73.20835391759412;const rows=[];for(let i=0;i<=25000;i++){const phi=lo+(hi-lo)*i/25000,q=intrinsic(camera([-60,phi])),p=raw(q[0]*R,q[1]*R);rows.push([phi,364+scale*(p[0]-origin[0]-center[0]),166-scale*(p[1]-origin[1]-center[1])].join(','));}const output=rows.join('\n')+'\n',file=resolve(root,'original-direct.csv');assert.equal(process.argv[2],'--check','Check-only fixture verifier');assert.equal(await readFile(file,'utf8'),output,'Original D3 direct-forward values must remain exact');const metadata=JSON.parse(await readFile(resolve(root,'source-and-fixture.json'),'utf8'));assert.equal(sha(output),metadata.fixtureSha256);assert.equal(sha(await readFile(fileURLToPath(import.meta.url))),metadata.producerSha256);console.log(JSON.stringify({passed:true,rows:rows.length,scope:'Original UMD direct point oracle; no use of original D3 resampled stream lambda shortcut and no Rust-derived projected expected point',fixtureSha256:sha(output)}));
